// This file contains a derived work based on routines and computations from the
// Naval Observatory Vector Astrometry Software (NOVAS), C Edition, developed by the
// U.S. Naval Observatory. NOVAS is public domain U.S. government work product.
// See https://aa.usno.navy.mil/software/novas/novas_info.php for the original software.
//
// This file ports:
//   - NOVAS31/NOVAS31/nutation.c            (iau2000a, iau2000b, nu2000k)
//   - novas.c's nutation/CIO family that ships alongside nutation.c in the real
//     NOVAS-C 3.1 distribution but is physically located in novas.c rather than
//     nutation.c: nutation, nutation_angles, fund_args, cio_array, cio_location,
//     cio_basis, ira_equinox. See the coordinating session for why these live here
//     rather than in ManagedNovas.Core.cs / ManagedNovas.Transforms.cs.
//
// NOTE ON set_racio_file: the vendored NOVAS-C 3.1 source in this repo does NOT
// define a 'set_racio_file' function -- cio_array() in the real source has the
// filename "cio_ra.bin" hardcoded. However, the real NOVAS31lib.dll wrapped by
// NINA.Astrometry/NOVAS.cs *does* export a 'set_racio_file' entry point
// (see NOVAS.cs's SetRACIOFile P/Invoke declaration), evidently from a later/patched
// NOVAS31 build. SetRacioFile()/CioArray() below have been adapted accordingly to
// accept a caller-supplied path rather than a hardcoded filename, per instructions.
//
// NOTE ON DATA FORMAT: CIO_RA.TXT is a plain-text file. Line 1 is a free-form
// identifier string (e.g. "CIO RA P03  @ 1.200d"). Every subsequent line holds one
// whitespace-separated record: <TDB Julian date> <RA of CIO in arcseconds>, e.g.
// "  2341951.400000       -1.94832757875929". Records are evenly spaced at a fixed
// interval (here 1.2 days). This mirrors exactly what the real cio_file.c converter
// utility reads via fscanf(" %lf %lf ", ...) before writing its binary cio_ra.bin.
// Because only the text form is vendored (and portability to macOS/Linux is the
// whole point of this port), CioArray() below reads CIO_RA.TXT directly and caches
// the parsed arrays in memory, rather than reproducing cio_array()'s original
// fseek()-based partial binary-record-cache strategy (a pure I/O performance detail
// of the C version). The returned values, bounds checks, and error codes match the
// original faithfully.

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;

namespace NINA.Astrometry {
    public static partial class ManagedNovas {

        /// <summary>
        /// Managed equivalent of NOVAS's "struct ra_of_cio" (novas.h): right ascension of the
        /// Celestial Intermediate Origin (CIO) with respect to the GCRS at a given TDB Julian date.
        /// </summary>
        public struct RaOfCio {
            /// <summary>TDB Julian date.</summary>
            public double JdTdb;
            /// <summary>Right ascension of the CIO with respect to the GCRS, in arcseconds.</summary>
            public double RaCio;
        }

        /// <summary>
        /// Port of NOVAS novas.c: fund_args(). Computes the fundamental arguments (mean elements)
        /// of the Sun and Moon (Simon et al. 1994, Sections 3.4-3.5).
        /// </summary>
        /// <param name="t">TDB time in Julian centuries since J2000.0.</param>
        /// <param name="a">Output: fundamental arguments in radians.
        /// a[0]=l (Moon mean anomaly), a[1]=l' (Sun mean anomaly),
        /// a[2]=F (Moon mean argument of latitude), a[3]=D (Moon mean elongation from Sun),
        /// a[4]=Omega (Moon mean longitude of ascending node).</param>
        public static void FundArgs(double t, double[] a) {
            const double Asec2Rad = 4.848136811095359935899141e-6;
            const double Asec360 = 1296000.0;

            a[0] = Mod(485868.249036 +
                      t * (1717915923.2178 +
                      t * (31.8792 +
                      t * (0.051635 +
                      t * (-0.00024470)))), Asec360) * Asec2Rad;

            a[1] = Mod(1287104.79305 +
                      t * (129596581.0481 +
                      t * (-0.5532 +
                      t * (0.000136 +
                      t * (-0.00001149)))), Asec360) * Asec2Rad;

            a[2] = Mod(335779.526232 +
                      t * (1739527262.8478 +
                      t * (-12.7512 +
                      t * (-0.001037 +
                      t * (0.00000417)))), Asec360) * Asec2Rad;

            a[3] = Mod(1072260.70369 +
                      t * (1602961601.2090 +
                      t * (-6.3706 +
                      t * (0.006593 +
                      t * (-0.00003169)))), Asec360) * Asec2Rad;

            a[4] = Mod(450160.398036 +
                      t * (-6962890.5431 +
                      t * (7.4722 +
                      t * (0.007702 +
                      t * (-0.00005939)))), Asec360) * Asec2Rad;
        }

        /// <summary>C fmod() equivalent (truncating remainder, matches C's fmod semantics used throughout NOVAS).</summary>
        private static double Mod(double x, double y) {
            return x % y;
        }

