        /// <summary>
        /// Port of NOVAS nutation.c: iau2000a(). Computes the forced nutation of the non-rigid
        /// Earth based on the full IAU 2000A nutation model (Simon et al. 1994; IERS Conventions
        /// 2003, Chapter 5). 678 luni-solar terms + 687 planetary terms.
        /// </summary>
        /// <param name="jdHigh">High-order part of TT Julian date.</param>
        /// <param name="jdLow">Low-order part of TT Julian date.</param>
        /// <param name="dpsi">Output: nutation (luni-solar + planetary) in longitude, in radians.</param>
        /// <param name="deps">Output: nutation (luni-solar + planetary) in obliquity, in radians.</param>
        public static void Iau2000A(double jdHigh, double jdLow, out double dpsi, out double deps) {
            const double T0 = 2451545.00000000;
            const double Asec2Rad = 4.848136811095359935899141e-6;
            const double TwoPi = 6.283185307179586476925287;

            double t, dp, de, arg, sarg, carg, factor, dpsils, depsls,
                al, alsu, af, ad, aom, alme, alve, alea, alma, alju, alsa, alur,
                alne, apa, dpsipl, depspl;
            var a = new double[5];

            // Luni-Solar argument multipliers:
            //     L     L'    F     D     Om

            // Interval between fundamental epoch J2000.0 and given date.
            t = ((jdHigh - T0) + jdLow) / 36525.0;

            // Compute fundamental arguments from Simon et al. (1994), in radians.
            FundArgs(t, a);

            // ** Luni-solar nutation. **

            // Initialize the nutation values.
            dp = 0.0;
            de = 0.0;

            // Summation of luni-solar nutation series (in reverse order).
            for (int i = 677; i >= 0; i--) {
                // Argument and functions.
                arg = Mod((double)Iau2000A_nals_t[i, 0] * a[0] +
                          (double)Iau2000A_nals_t[i, 1] * a[1] +
                          (double)Iau2000A_nals_t[i, 2] * a[2] +
                          (double)Iau2000A_nals_t[i, 3] * a[3] +
                          (double)Iau2000A_nals_t[i, 4] * a[4], TwoPi);

                sarg = Math.Sin(arg);
                carg = Math.Cos(arg);

                // Term.
                dp += (Iau2000A_cls_t[i, 0] + Iau2000A_cls_t[i, 1] * t) * sarg
                        + Iau2000A_cls_t[i, 2] * carg;
                de += (Iau2000A_cls_t[i, 3] + Iau2000A_cls_t[i, 4] * t) * carg
                        + Iau2000A_cls_t[i, 5] * sarg;
            }

            // Convert from 0.1 microarcsec units to radians.
            factor = 1.0e-7 * Asec2Rad;
            dpsils = dp * factor;
            depsls = de * factor;

            // ** Planetary nutation. **

            // Mean anomaly of the Moon.
            al = Mod(2.35555598 + 8328.6914269554 * t, TwoPi);

            // Mean anomaly of the Sun.
            alsu = Mod(6.24006013 + 628.301955 * t, TwoPi);

            // Mean argument of the latitude of the Moon.
            af = Mod(1.627905234 + 8433.466158131 * t, TwoPi);

            // Mean elongation of the Moon from the Sun.
            ad = Mod(5.198466741 + 7771.3771468121 * t, TwoPi);

            // Mean longitude of the ascending node of the Moon.
            aom = Mod(2.18243920 - 33.757045 * t, TwoPi);

            // General accumulated precession in longitude.
            apa = (0.02438175 + 0.00000538691 * t) * t;

            // Planetary longitudes, Mercury through Neptune (Souchay et al. 1999).
            alme = Mod(4.402608842 + 2608.7903141574 * t, TwoPi);
            alve = Mod(3.176146697 + 1021.3285546211 * t, TwoPi);
            alea = Mod(1.753470314 + 628.3075849991 * t, TwoPi);
            alma = Mod(6.203480913 + 334.0612426700 * t, TwoPi);
            alju = Mod(0.599546497 + 52.9690962641 * t, TwoPi);
            alsa = Mod(0.874016757 + 21.3299104960 * t, TwoPi);
            alur = Mod(5.481293871 + 7.4781598567 * t, TwoPi);
            alne = Mod(5.321159000 + 3.8127774000 * t, TwoPi);

            // Initialize the nutation values.
            dp = 0.0;
            de = 0.0;

            // Summation of planetary nutation series (in reverse order).
            for (int i = 686; i >= 0; i--) {
                // Argument and functions.
                arg = Mod((double)Iau2000A_napl_t[i, 0] * al +
                          (double)Iau2000A_napl_t[i, 1] * alsu +
                          (double)Iau2000A_napl_t[i, 2] * af +
                          (double)Iau2000A_napl_t[i, 3] * ad +
                          (double)Iau2000A_napl_t[i, 4] * aom +
                          (double)Iau2000A_napl_t[i, 5] * alme +
                          (double)Iau2000A_napl_t[i, 6] * alve +
                          (double)Iau2000A_napl_t[i, 7] * alea +
                          (double)Iau2000A_napl_t[i, 8] * alma +
                          (double)Iau2000A_napl_t[i, 9] * alju +
                          (double)Iau2000A_napl_t[i, 10] * alsa +
                          (double)Iau2000A_napl_t[i, 11] * alur +
                          (double)Iau2000A_napl_t[i, 12] * alne +
                          (double)Iau2000A_napl_t[i, 13] * apa, TwoPi);

                sarg = Math.Sin(arg);
                carg = Math.Cos(arg);

                // Term.
                dp += Iau2000A_cpl_t[i, 0] * sarg + Iau2000A_cpl_t[i, 1] * carg;
                de += Iau2000A_cpl_t[i, 2] * sarg + Iau2000A_cpl_t[i, 3] * carg;
            }

            dpsipl = dp * factor;
            depspl = de * factor;

            // Total: Add planetary and luni-solar components.
            dpsi = dpsipl + dpsils;
            deps = depspl + depsls;
        }

