        /// <summary>
        /// Port of NOVAS nutation.c: iau2000b(). Computes the forced nutation of the non-rigid
        /// Earth based on the IAU 2000B (abridged) precession/nutation model (McCarthy &amp; Luzum
        /// 2003). Reproduces IAU 2000A to within 1 milliarcsecond over 1995-2020. 77 luni-solar
        /// terms plus fixed planetary correction terms.
        /// </summary>
        /// <param name="jdHigh">High-order part of TT Julian date.</param>
        /// <param name="jdLow">Low-order part of TT Julian date.</param>
        /// <param name="dpsi">Output: nutation (luni-solar + planetary) in longitude, in radians.</param>
        /// <param name="deps">Output: nutation (luni-solar + planetary) in obliquity, in radians.</param>
        public static void Iau2000B(double jdHigh, double jdLow, out double dpsi, out double deps) {
            const double T0 = 2451545.00000000;
            const double Asec2Rad = 4.848136811095359935899141e-6;
            const double Asec360 = 1296000.0;
            const double TwoPi = 6.283185307179586476925287;

            // Planetary nutation (arcsec). These fixed terms account for the omission of the
            // long-period planetary terms in the truncated model.
            double dpplan = -0.000135;
            double deplan = 0.000388;

            double t, el, elp, f, d, om, arg, dp, de, sarg, carg, factor, dpsils,
                depsls, dpsipl, depspl;

            // Luni-Solar argument multipliers:
            //     L     L'    F     D     Om

            // Interval between fundamental epoch J2000.0 and given date.
            t = ((jdHigh - T0) + jdLow) / 36525.0;

            // ** Luni-solar nutation. **
            // Fundamental (Delaunay) arguments from Simon et al. (1994), in radians.

            // Mean anomaly of the Moon.
            el = Mod(485868.249036 +
                   t * 1717915923.2178, Asec360) * Asec2Rad;

            // Mean anomaly of the Sun.
            elp = Mod(1287104.79305 +
                     t * 129596581.0481, Asec360) * Asec2Rad;

            // Mean argument of the latitude of the Moon.
            f = Mod(335779.526232 +
                     t * 1739527262.8478, Asec360) * Asec2Rad;

            // Mean elongation of the Moon from the Sun.
            d = Mod(1072260.70369 +
                     t * 1602961601.2090, Asec360) * Asec2Rad;

            // Mean longitude of the ascending node of the Moon.
            om = Mod(450160.398036 -
                     t * 6962890.5431, Asec360) * Asec2Rad;

            // Initialize the nutation values.
            dp = 0.0;
            de = 0.0;

            // Summation of luni-solar nutation series (in reverse order).
            for (int i = 76; i >= 0; i--) {
                // Argument and functions.
                arg = Mod((double)Iau2000B_nals_t[i, 0] * el +
                          (double)Iau2000B_nals_t[i, 1] * elp +
                          (double)Iau2000B_nals_t[i, 2] * f +
                          (double)Iau2000B_nals_t[i, 3] * d +
                          (double)Iau2000B_nals_t[i, 4] * om, TwoPi);

                sarg = Math.Sin(arg);
                carg = Math.Cos(arg);

                // Term.
                dp += (Iau2000B_cls_t[i, 0] + Iau2000B_cls_t[i, 1] * t) * sarg
                        + Iau2000B_cls_t[i, 2] * carg;
                de += (Iau2000B_cls_t[i, 3] + Iau2000B_cls_t[i, 4] * t) * carg
                        + Iau2000B_cls_t[i, 5] * sarg;
            }

            // Convert from 0.1 microarcsec units to radians.
            factor = 1.0e-7 * Asec2Rad;
            dpsils = dp * factor;
            depsls = de * factor;

            // ** Planetary nutation. **
            // Fixed terms to allow for long-period nutation, in radians.
            dpsipl = dpplan * Asec2Rad;
            depspl = deplan * Asec2Rad;

            // Total: Add planetary and luni-solar components.
            dpsi = dpsipl + dpsils;
            deps = depspl + depsls;
        }

