        /// <summary>
        /// Port of NOVAS nutation.c: nu2000k(). NU2000K -- a truncated, faster-evaluating version
        /// of IAU 2000A using Simon et al. (1994) fundamental arguments throughout. Agrees with
        /// IAU 2000A at the 0.1 milliarcsecond level from 1700-2300. This is the model NOVAS uses
        /// by default for "reduced accuracy" (see nutation_angles() below). 323 luni-solar terms
        /// plus 165 planetary terms.
        /// </summary>
        /// <param name="jdHigh">High-order part of TT Julian date.</param>
        /// <param name="jdLow">Low-order part of TT Julian date.</param>
        /// <param name="dpsi">Output: nutation (luni-solar + planetary) in longitude, in radians.</param>
        /// <param name="deps">Output: nutation (luni-solar + planetary) in obliquity, in radians.</param>
        public static void Nu2000K(double jdHigh, double jdLow, out double dpsi, out double deps) {
            const double T0 = 2451545.00000000;
            const double Asec2Rad = 4.848136811095359935899141e-6;
            const double TwoPi = 6.283185307179586476925287;

            double t, dp, de, arg, sarg, carg, factor, dpsils,
                depsls, alme, alve, alea, alma, alju, alsa, alur, alne, apa,
                dpsipl, depspl;
            var a = new double[5];

            // Luni-Solar argument multipliers:
            //     L     L'    F     D     Om

            // Interval between fundamental epoch J2000.0 and given date.
            t = ((jdHigh - T0) + jdLow) / 36525.0;

            // Compute fundamental arguments from Simon et al. (1994), in radians.
            FundArgs(t, a);

            // ** Luni-solar nutation. **

            // Initialize the nutation values.
            dp = 0.0;
            de = 0.0;

            // Summation of luni-solar nutation series (in reverse order).
            for (int i = 322; i >= 0; i--) {
                // Argument and functions.
                arg = Mod((double)Nu2000K_nals_t[i, 0] * a[0] +
                          (double)Nu2000K_nals_t[i, 1] * a[1] +
                          (double)Nu2000K_nals_t[i, 2] * a[2] +
                          (double)Nu2000K_nals_t[i, 3] * a[3] +
                          (double)Nu2000K_nals_t[i, 4] * a[4], TwoPi);

                sarg = Math.Sin(arg);
                carg = Math.Cos(arg);

                // Term.
                dp += (Nu2000K_cls_t[i, 0] + Nu2000K_cls_t[i, 1] * t) * sarg
                        + Nu2000K_cls_t[i, 2] * carg;
                de += (Nu2000K_cls_t[i, 3] + Nu2000K_cls_t[i, 4] * t) * carg
                        + Nu2000K_cls_t[i, 5] * sarg;
            }

            // Convert from 0.1 microarcsec units to radians.
            factor = 1.0e-7 * Asec2Rad;
            dpsils = dp * factor;
            depsls = de * factor;

            // ** Planetary nutation. **
            // Planetary longitudes, Mercury through Neptune, wrt mean dynamical ecliptic and
            // equinox of J2000, with high order terms omitted (Simon et al. 1994, 5.8.1-5.8.8).
            alme = Mod(4.402608842461 + 2608.790314157421 * t, TwoPi);
            alve = Mod(3.176146696956 + 1021.328554621099 * t, TwoPi);
            alea = Mod(1.753470459496 + 628.307584999142 * t, TwoPi);
            alma = Mod(6.203476112911 + 334.061242669982 * t, TwoPi);
            alju = Mod(0.599547105074 + 52.969096264064 * t, TwoPi);
            alsa = Mod(0.874016284019 + 21.329910496032 * t, TwoPi);
            alur = Mod(5.481293871537 + 7.478159856729 * t, TwoPi);
            alne = Mod(5.311886286677 + 3.813303563778 * t, TwoPi);

            // General precession in longitude (Simon et al. 1994), equivalent to
            // 5028.8200 arcsec/cy at J2000.
            apa = (0.024380407358 + 0.000005391235 * t) * t;

            // Initialize the nutation values.
            dp = 0.0;
            de = 0.0;

            // Summation of planetary nutation series (in reverse order).
            for (int i = 164; i >= 0; i--) {
                // Argument and functions.
                arg = Mod((double)Nu2000K_napl_t[i, 0] * a[0] +
                          (double)Nu2000K_napl_t[i, 1] * a[1] +
                          (double)Nu2000K_napl_t[i, 2] * a[2] +
                          (double)Nu2000K_napl_t[i, 3] * a[3] +
                          (double)Nu2000K_napl_t[i, 4] * a[4] +
                          (double)Nu2000K_napl_t[i, 5] * alme +
                          (double)Nu2000K_napl_t[i, 6] * alve +
                          (double)Nu2000K_napl_t[i, 7] * alea +
                          (double)Nu2000K_napl_t[i, 8] * alma +
                          (double)Nu2000K_napl_t[i, 9] * alju +
                          (double)Nu2000K_napl_t[i, 10] * alsa +
                          (double)Nu2000K_napl_t[i, 11] * alur +
                          (double)Nu2000K_napl_t[i, 12] * alne +
                          (double)Nu2000K_napl_t[i, 13] * apa, TwoPi);

                sarg = Math.Sin(arg);
                carg = Math.Cos(arg);

                // Term.
                dp += Nu2000K_cpl_t[i, 0] * sarg + Nu2000K_cpl_t[i, 1] * carg;
                de += Nu2000K_cpl_t[i, 2] * sarg + Nu2000K_cpl_t[i, 3] * carg;
            }

            dpsipl = dp * factor;
            depspl = de * factor;

            // Total: Add planetary and luni-solar components.
            dpsi = dpsipl + dpsils;
            deps = depspl + depsls;
        }

        /// <summary>
        /// Port of NOVAS novas.c: nutation_angles(). Returns nutation in longitude and obliquity
        /// for a given TDB Julian date. The model used depends on 'accuracy': full accuracy (0)
        /// always uses IAU 2000A; reduced accuracy (1) uses NU2000K by default (matching NOVAS's
        /// default 'low_acc_choice' = 1).
        /// </summary>
        /// <param name="t">TDB time in Julian centuries since J2000.0.</param>
        /// <param name="accuracy">0 = full accuracy, 1 = reduced accuracy.</param>
        /// <param name="dpsi">Output: nutation in longitude, in arcseconds.</param>
        /// <param name="deps">Output: nutation in obliquity, in arcseconds.</param>
        public static void NutationAngles(double t, short accuracy, out double dpsi, out double deps) {
            const double T0 = 2451545.00000000;
            const double Asec2Rad = 4.848136811095359935899141e-6;

            // Set the value of 'low_acc_choice' according to the rules explained in the original
            // NOVAS prolog: 1 (default) => NU2000K, 2 => IAU 2000B.
            short lowAccChoice = 1;

            double t1 = t * 36525.0;

            if (accuracy == 0) {
                // High accuracy mode -- use IAU 2000A.
                Iau2000A(T0, t1, out dpsi, out deps);
            } else {
                // Low accuracy mode -- model depends upon value of 'low_acc_choice'.
                switch (lowAccChoice) {
                    case 2: // use IAU 2000B
                        Iau2000B(T0, t1, out dpsi, out deps);
                        break;

                    case 1: // use NU2000K
                    default:
                        Nu2000K(T0, t1, out dpsi, out deps);
                        break;
                }
            }

            // Convert output to arcseconds.
            dpsi /= Asec2Rad;
            deps /= Asec2Rad;
        }

        /// <summary>
        /// Port of NOVAS novas.c: nutation(). Nutates equatorial rectangular coordinates from
        /// mean equator and equinox of epoch to true equator and equinox of epoch (or applies the
        /// inverse transformation).
        /// </summary>
        /// <param name="jdTdb">TDB Julian date of epoch.</param>
        /// <param name="direction">0 = mean-to-true, non-zero = true-to-mean (inverse).</param>
        /// <param name="accuracy">0 = full accuracy, 1 = reduced accuracy.</param>
        /// <param name="pos">Input position vector, geocentric equatorial rectangular coordinates,
        /// referred to mean equator and equinox of epoch (or true, if inverse).</param>
        /// <param name="pos2">Output position vector, referred to true equator and equinox of
        /// epoch (or mean, if inverse).</param>
        public static void Nutation(double jdTdb, short direction, short accuracy, double[] pos, double[] pos2) {
            const double Deg2Rad = 0.017453292519943296;
            const double Asec2Rad = 4.848136811095359935899141e-6;

            // Call 'ETilt' (ManagedNovas.Core.cs) to get the obliquity and nutation angles.
            double oblm = 0.0, oblt = 0.0, eqeq = 0.0, psi = 0.0, eps = 0.0;
            ETilt(jdTdb, accuracy, ref oblm, ref oblt, ref eqeq, ref psi, ref eps);

            double cobm = Math.Cos(oblm * Deg2Rad);
            double sobm = Math.Sin(oblm * Deg2Rad);
            double cobt = Math.Cos(oblt * Deg2Rad);
            double sobt = Math.Sin(oblt * Deg2Rad);
            double cpsi = Math.Cos(psi * Asec2Rad);
            double spsi = Math.Sin(psi * Asec2Rad);

            // Nutation rotation matrix follows.
            double xx = cpsi;
            double yx = -spsi * cobm;
            double zx = -spsi * sobm;
            double xy = spsi * cobt;
            double yy = cpsi * cobm * cobt + sobm * sobt;
            double zy = cpsi * sobm * cobt - cobm * sobt;
            double xz = spsi * sobt;
            double yz = cpsi * cobm * sobt - sobm * cobt;
            double zz = cpsi * sobm * sobt + cobm * cobt;

            if (direction == 0) {
                // Perform rotation.
                pos2[0] = xx * pos[0] + yx * pos[1] + zx * pos[2];
                pos2[1] = xy * pos[0] + yy * pos[1] + zy * pos[2];
                pos2[2] = xz * pos[0] + yz * pos[1] + zz * pos[2];
            } else {
                // Perform inverse rotation.
                pos2[0] = xx * pos[0] + xy * pos[1] + xz * pos[2];
                pos2[1] = yx * pos[0] + yy * pos[1] + yz * pos[2];
                pos2[2] = zx * pos[0] + zy * pos[1] + zz * pos[2];
            }
        }

        #region CIO locator file (cio_file.c / novas.c CIO family)

        private static string _racioFilePath;
        private static bool _cioArrayLoaded;
        private static double[] _cioArrayJd;
        private static double[] _cioArrayRa;
        private static double _cioArrayJdBeg;
        private static double _cioArrayJdEnd;
        private static double _cioArrayTInt;
        private static long _cioArrayNRecs;

        /// <summary>
        /// Adaptation of NOVAS's 'set_racio_file' (exported by the real NOVAS31lib.dll wrapped by
        /// NOVAS.cs, though not present as source in this repo's vendored nutation/cio_file.c --
        /// see the file header for details). Registers the path to the CIO right-ascension data
        /// file (the text-format CIO_RA.TXT vendored in this repo) that CioArray() will read from.
        /// Call this once before any CioLocation()/CioArray() call. Passing a new path invalidates
        /// any previously cached table.
        /// </summary>
        /// <param name="fileName">Full path to CIO_RA.TXT (or an equivalent CIO right-ascension
        /// text data file in the same format).</param>
        public static void SetRacioFile(string fileName) {
            if (_racioFilePath != fileName) {
                _racioFilePath = fileName;
                _cioArrayLoaded = false;
                _cioArrayJd = null;
                _cioArrayRa = null;
            }
        }

        /// <summary>
        /// Port of NOVAS novas.c: cio_array(). Given an input TDB Julian date and the number of
        /// data points desired, returns a set of Julian dates and corresponding values of the
        /// GCRS right ascension of the CIO, centered (at least approximately) on the requested
        /// date.
        ///
        /// ADAPTATION NOTE: the original reads a pre-built binary random-access file
        /// ('cio_ra.bin', produced from CIO_RA.TXT by the separate cio_file.c converter utility)
        /// and does incremental partial-record re-reads for performance. Since only the text
        /// CIO_RA.TXT is vendored in this port (see SetRacioFile), this implementation instead
        /// parses the whole text file into memory once (cached across calls) and then applies the
        /// exact same index/bounds arithmetic and error codes as the original to select the
        /// requested window. Numerical results and error semantics match the original; only the
        /// I/O strategy differs.
        /// </summary>
        /// <param name="jdTdb">TDB Julian date.</param>
        /// <param name="nPts">Number of Julian dates / RA values requested (2-20 inclusive).</param>
        /// <param name="cio">Output array (caller-allocated, length >= nPts) to receive the CIO
        /// right ascension time series.</param>
        /// <returns>
        /// 0 = OK; 1 = error opening/parsing the CIO file; 2 = 'jdTdb' not in the range of the CIO
        /// file; 3 = 'nPts' out of range; 6 = 'jdTdb' too close to either end of the CIO file to
        /// fit nPts data points. (Error codes 4 and 5 in the original signal memory-allocation
        /// failure for internal working arrays during incremental binary reads; they do not apply
        /// to this in-memory implementation and are not produced here.)
        /// </returns>
        public static short CioArray(double jdTdb, long nPts, RaOfCio[] cio) {
            const long minPts = 2;
            const long maxPts = 20;

            if (!_cioArrayLoaded) {
                if (string.IsNullOrEmpty(_racioFilePath) || !File.Exists(_racioFilePath)) {
                    return 1;
                }

                try {
                    var jdList = new List<double>();
                    var raList = new List<double>();

                    using (var reader = new StreamReader(_racioFilePath)) {
                        // First line of CIO_RA.TXT is a free-form identifier, not a data record
                        // (mirrors the original converter's fgets(identifier, ...) call).
                        string identifierLine = reader.ReadLine();
                        if (identifierLine == null) {
                            return 1;
                        }

                        string line;
                        while ((line = reader.ReadLine()) != null) {
                            if (string.IsNullOrWhiteSpace(line)) {
                                continue;
                            }
                            var parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
                            if (parts.Length < 2) {
                                continue;
                            }
                            double jd = double.Parse(parts[0], CultureInfo.InvariantCulture);
                            double ra = double.Parse(parts[1], CultureInfo.InvariantCulture);
                            jdList.Add(jd);
                            raList.Add(ra);
                        }
                    }

                    if (jdList.Count < 2) {
                        return 1;
                    }

                    _cioArrayJd = jdList.ToArray();
                    _cioArrayRa = raList.ToArray();
                    _cioArrayJdBeg = _cioArrayJd[0];
                    _cioArrayTInt = _cioArrayJd[1] - _cioArrayJd[0];
                    _cioArrayJdEnd = _cioArrayJd[_cioArrayJd.Length - 1];
                    _cioArrayNRecs = _cioArrayJd.Length;
                    _cioArrayLoaded = true;
                } catch (IOException) {
                    return 1;
                } catch (FormatException) {
                    return 1;
                }
            }

            // Check the input data against limits.
            if ((jdTdb < _cioArrayJdBeg) || (jdTdb > _cioArrayJdEnd)) {
                return 2;
            }

            if ((nPts < minPts) || (nPts > maxPts)) {
                return 3;
            }

            // Calculate the record number of the record immediately preceding the date of
            // interest: the "index record" (1-based, matching the original).
            long indexRec = (long)((jdTdb - _cioArrayJdBeg) / _cioArrayTInt) + 1L;

            // Test the range of 'nPts' values centered on 'indexRec' to be sure the range of
            // values requested falls within the file limits.
            long halfInt = (nPts / 2L) - 1L;
            long loLimit = indexRec - halfInt;
            long hiLimit = indexRec + (nPts - halfInt - 1L);

            if ((loLimit < 1L) || (hiLimit > _cioArrayNRecs)) {
                return 6;
            }

            for (long i = 0; i < nPts; i++) {
                long srcIndex = loLimit - 1L + i; // loLimit is 1-based; array is 0-based.
                cio[i].JdTdb = _cioArrayJd[srcIndex];
                cio[i].RaCio = _cioArrayRa[srcIndex];
            }

            return 0;
        }

        private static bool _cioLocationFirstCall = true;
        private static bool _cioLocationUseFile;
        private static double _cioLocationTLast;
        private static double _cioLocationRaLast;
        private static short _cioLocationRefSysLast;
        private static RaOfCio[] _cioLocationBuffer;

        /// <summary>
        /// Port of NOVAS novas.c: cio_location(). Returns the location of the CIO for a given
        /// Julian date, as a right ascension with respect to either the GCRS origin or the true
        /// equinox of date.
        /// </summary>
        /// <param name="jdTdb">TDB Julian date.</param>
        /// <param name="accuracy">0 = full accuracy, 1 = reduced accuracy.</param>
        /// <param name="raCio">Output: right ascension of the CIO, in hours.</param>
        /// <param name="refSys">Output: reference system of raCio. 1 = GCRS, 2 = true equator and
        /// equinox of date.</param>
        /// <returns>0 = OK; &gt;10 = 10 + the error code from CioArray().</returns>
        public static short CioLocation(double jdTdb, short accuracy, out double raCio, out short refSys) {
            const long nPts = 6;
            short error = 0;

            // Check (once) whether the external CIO right-ascension file is usable.
            if (_cioLocationFirstCall) {
                _cioLocationUseFile = !string.IsNullOrEmpty(_racioFilePath) && File.Exists(_racioFilePath);
            }

            // Check if previously computed RA value can be re-used.
            if (Math.Abs(jdTdb - _cioLocationTLast) <= 1.0e-8) {
                raCio = _cioLocationRaLast;
                refSys = _cioLocationRefSysLast;
                return 0;
            }

            if (_cioLocationUseFile) {
                // -----------------------------
                // Interpolate values from file.
                // -----------------------------
                if (_cioLocationFirstCall) {
                    _cioLocationBuffer = new RaOfCio[nPts];
                    _cioLocationFirstCall = false;
                }

                error = CioArray(jdTdb, nPts, _cioLocationBuffer);
                if (error != 0) {
                    raCio = 0.0;
                    refSys = 0;
                    return (short)(error + 10);
                }

                // Perform Lagrangian interpolation for the RA at 'jdTdb'.
                raCio = 0.0;
                for (long j = 0; j < nPts; j++) {
                    double p = 1.0;
                    for (long i = 0; i < nPts; i++) {
                        if (i != j) {
                            p *= (jdTdb - _cioLocationBuffer[i].JdTdb) /
                                 (_cioLocationBuffer[j].JdTdb - _cioLocationBuffer[i].JdTdb);
                        }
                    }
                    raCio += p * _cioLocationBuffer[j].RaCio;
                }

                raCio /= 54000.0;
                refSys = 1;
            } else {
                // -------------------------
                // Use internal computation.
                // -------------------------
                if (_cioLocationFirstCall) {
                    _cioLocationFirstCall = false;
                }

                double eqOrigins = IraEquinox(jdTdb, 1, accuracy);

                raCio = -eqOrigins;
                refSys = 2;
            }

            _cioLocationTLast = jdTdb;
            _cioLocationRaLast = raCio;
            _cioLocationRefSysLast = refSys;

            return error;
        }

        private static short _cioBasisRefSysLast;
        private static double _cioBasisTLast;
        private static readonly double[] _cioBasisXx = new double[3];
        private static readonly double[] _cioBasisYy = new double[3];
        private static readonly double[] _cioBasisZz = new double[3];

        /// <summary>
        /// Port of NOVAS novas.c: cio_basis(). Computes the orthonormal basis vectors, with
        /// respect to the GCRS, of the celestial intermediate system defined by the CIP (z
        /// direction) and the CIO (x direction).
        /// </summary>
        /// <param name="jdTdb">TDB Julian date of epoch.</param>
        /// <param name="raCio">Right ascension of the CIO at epoch (hours).</param>
        /// <param name="refSys">Reference system of raCio (output from CioLocation()): 1 = GCRS,
        /// 2 = true equator and equinox of date.</param>
        /// <param name="accuracy">0 = full accuracy, 1 = reduced accuracy.</param>
        /// <param name="x">Output: unit vector toward the CIO (GCRS equatorial rectangular).</param>
        /// <param name="y">Output: unit vector completing the right-handed triad (GCRS).</param>
        /// <param name="z">Output: unit vector toward the north celestial pole (GCRS).</param>
        /// <returns>0 = OK; 1 = invalid 'refSys'.</returns>
        public static short CioBasis(double jdTdb, double raCio, short refSys, short accuracy,
                                      double[] x, double[] y, double[] z) {
            const double T0 = 2451545.00000000;
            const double Deg2Rad = 0.017453292519943296;

            short error = 0;
            double[] z0 = { 0.0, 0.0, 1.0 };
            double[] w0 = new double[3];
            double[] w1 = new double[3];
            double[] w2 = new double[3];

            // Compute unit vector z toward celestial pole.
            if ((Math.Abs(jdTdb - _cioBasisTLast) > 1.0e-8) || (refSys != _cioBasisRefSysLast)) {
                Nutation(jdTdb, -1, accuracy, z0, w1);
                Precession(jdTdb, w1, T0, w2);
                FrameTie(w2, -1, _cioBasisZz);

                _cioBasisTLast = jdTdb;
                _cioBasisRefSysLast = refSys;
            } else {
                for (int i = 0; i < 3; i++) {
                    x[i] = _cioBasisXx[i];
                    y[i] = _cioBasisYy[i];
                    z[i] = _cioBasisZz[i];
                }
                return error;
            }

            // Now compute unit vectors x and y. Method used depends on the reference system in
            // which right ascension of the CIO is given.
            switch (refSys) {
                case 1: {
                    // ----------------------------
                    // RA of CIO expressed in GCRS.
                    // ----------------------------
                    double sinra = Math.Sin(raCio * 15.0 * Deg2Rad);
                    double cosra = Math.Cos(raCio * 15.0 * Deg2Rad);
                    _cioBasisXx[0] = _cioBasisZz[2] * cosra;
                    _cioBasisXx[1] = _cioBasisZz[2] * sinra;
                    _cioBasisXx[2] = -_cioBasisZz[0] * cosra - _cioBasisZz[1] * sinra;

                    // Normalize vector x.
                    double xmag = Math.Sqrt(_cioBasisXx[0] * _cioBasisXx[0] + _cioBasisXx[1] * _cioBasisXx[1] + _cioBasisXx[2] * _cioBasisXx[2]);
                    _cioBasisXx[0] /= xmag;
                    _cioBasisXx[1] /= xmag;
                    _cioBasisXx[2] /= xmag;

                    // Compute unit vector y orthogonal to x and z (y = z cross x).
                    _cioBasisYy[0] = _cioBasisZz[1] * _cioBasisXx[2] - _cioBasisZz[2] * _cioBasisXx[1];
                    _cioBasisYy[1] = _cioBasisZz[2] * _cioBasisXx[0] - _cioBasisZz[0] * _cioBasisXx[2];
                    _cioBasisYy[2] = _cioBasisZz[0] * _cioBasisXx[1] - _cioBasisZz[1] * _cioBasisXx[0];
                    break;
                }

                case 2: {
                    // ----------------------------------------------------------
                    // RA of CIO expressed in equator-and-equinox-of-date system.
                    // ----------------------------------------------------------
                    w0[0] = Math.Cos(raCio * 15.0 * Deg2Rad);
                    w0[1] = Math.Sin(raCio * 15.0 * Deg2Rad);
                    w0[2] = 0.0;

                    // Rotate the vector into the GCRS to form unit vector x.
                    Nutation(jdTdb, -1, accuracy, w0, w1);
                    Precession(jdTdb, w1, T0, w2);
                    FrameTie(w2, -1, _cioBasisXx);

                    // Compute unit vector y orthogonal to x and z (y = z cross x).
                    _cioBasisYy[0] = _cioBasisZz[1] * _cioBasisXx[2] - _cioBasisZz[2] * _cioBasisXx[1];
                    _cioBasisYy[1] = _cioBasisZz[2] * _cioBasisXx[0] - _cioBasisZz[0] * _cioBasisXx[2];
                    _cioBasisYy[2] = _cioBasisZz[0] * _cioBasisXx[1] - _cioBasisZz[1] * _cioBasisXx[0];
                    break;
                }

                default:
                    // ---------------------------
                    // Invalid value of 'refSys'.
                    // ---------------------------
                    for (int i = 0; i < 3; i++) {
                        _cioBasisXx[i] = 0.0;
                        _cioBasisYy[i] = 0.0;
                        _cioBasisZz[i] = 0.0;
                    }
                    error = 1;
                    break;
            }

            // Load the x, y, and z arrays.
            for (int i = 0; i < 3; i++) {
                x[i] = _cioBasisXx[i];
                y[i] = _cioBasisYy[i];
                z[i] = _cioBasisZz[i];
            }

            return error;
        }

        private static short _iraEquinoxAccLast = 99;
        private static double _iraEquinoxTLast;
        private static double _iraEquinoxEqEq;

        /// <summary>
        /// Port of NOVAS novas.c: ira_equinox(). Computes the intermediate right ascension of the
        /// equinox at the input Julian date, using an analytical expression for the accumulated
        /// precession in right ascension. For the true equinox, the result is the equation of the
        /// origins. This is the "no external CIO file" fallback path used by CioLocation().
        /// </summary>
        /// <param name="jdTdb">TDB Julian date.</param>
        /// <param name="equinox">0 = mean equinox, 1 = true equinox.</param>
        /// <param name="accuracy">0 = full accuracy, 1 = reduced accuracy.</param>
        /// <returns>Intermediate right ascension of the equinox, in hours (+ or -). If equinox = 1,
        /// this is the equation of the origins.</returns>
        public static double IraEquinox(double jdTdb, short equinox, short accuracy) {
            const double T0 = 2451545.00000000;

            double t = (jdTdb - T0) / 36525.0;

            // For the true equinox, obtain the equation of the equinoxes in time seconds, which
            // includes the 'complementary terms'.
            if (equinox == 1) {
                if ((Math.Abs(jdTdb - _iraEquinoxTLast) > 1.0e-8) || (accuracy != _iraEquinoxAccLast)) {
                    double u = 0.0, v = 0.0, w = 0.0, x = 0.0;
                    ETilt(jdTdb, accuracy, ref u, ref v, ref _iraEquinoxEqEq, ref w, ref x);
                    _iraEquinoxTLast = jdTdb;
                    _iraEquinoxAccLast = accuracy;
                }
            } else {
                _iraEquinoxEqEq = 0.0;
            }

            // Precession in RA in arcseconds taken from the reference.
            double precRa = 0.014506 +
                (((( -0.0000000368 * t
                     - 0.000029956) * t
                     - 0.00000044) * t
                     + 1.3915817) * t
                     + 4612.156534) * t;

            return -(precRa / 15.0 + _iraEquinoxEqEq) / 3600.0;
        }

        #endregion CIO locator file (cio_file.c / novas.c CIO family)
    }
}
